// ── 픽셀 스프라이트 렌더러 (오프스크린 캐싱) ─────────────────────
// 매 프레임 픽셀 단위 fillRect를 반복하지 않도록, 스프라이트를 1픽셀=1px
// 오프스크린 캔버스에 한 번만 굽고 이후에는 drawImage 한 번으로 그린다.
const _spriteCache = new WeakMap();

function _bakeSprite(sprite, colorMap) {
    const h = sprite.length, w = sprite[0].length;
    const off = document.createElement('canvas');
    off.width = w; off.height = h;
    const octx = off.getContext('2d');
    for (let row = 0; row < h; row++) {
        for (let col = 0; col < w; col++) {
            const pixel = sprite[row][col];
            if (pixel !== 0 && colorMap[pixel]) {
                octx.fillStyle = colorMap[pixel];
                octx.fillRect(col, row, 1, 1);
            }
        }
    }
    return off;
}

function drawPixelSprite(sprite, colorMap, x, y, scale = PIXEL_SCALE) {
    if (!sprite || !colorMap) return;
    let baked = _spriteCache.get(sprite);
    if (!baked) {
        baked = _bakeSprite(sprite, colorMap);
        _spriteCache.set(sprite, baked);
    }
    ctx.imageSmoothingEnabled = false;
    ctx.drawImage(baked, x, y, baked.width * scale, baked.height * scale);
}
